mapper.insert:

INSERT INTO chat_read (
    chat_message_no,
    project_member_no
)
SELECT
    M.chat_message_no,
    #{projectMemberNo}
FROM chat_message M
WHERE M.chat_channel_no = #{channelNo}
  AND NOT EXISTS (
      SELECT 1
      FROM chat_read CR
      WHERE CR.chat_message_no = M.chat_message_no
        AND CR.project_member_no = #{projectMemberNo}
  )
